import ast, re, sys, pathlib
root = pathlib.Path(".")
disp = root/".claude/dispatcher/dispatch.py"
src = disp.read_text(encoding="utf-8")
tree = ast.parse(src)
bound = {}  # name -> lineno
for n in tree.body:
    if isinstance(n, ast.ImportFrom):
        for a in n.names: bound[a.asname or a.name] = n.lineno
    elif isinstance(n, ast.Import):
        for a in n.names: bound[(a.asname or a.name).split(".")[0]] = n.lineno
# internal use: Name loads / Attribute bases anywhere
used = set()
for n in ast.walk(tree):
    if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load): used.add(n.id)
files = [p for p in root.rglob("*.py") if "worktrees" not in p.parts[:3] and p != disp and ".git" not in p.parts]
texts = {p: p.read_text(encoding="utf-8", errors="ignore") for p in files}
users = {p: t for p, t in texts.items() if re.search(r"\bimport dispatch\b|from dispatch import", t)}
res = {"A": [], "B": [], "C": []}
for name, ln in bound.items():
    ext_prod, ext_test = [], []
    for p, t in users.items():
        if re.search(rf"\b(D|dispatch)\.{re.escape(name)}\b|[\"']{re.escape(name)}[\"']|from dispatch import[^\n]*\b{re.escape(name)}\b", t):
            (ext_test if p.name.startswith("test_") or "tests" in p.parts else ext_prod).append(p.name)
    cat = "C" if name in used and not ext_prod and not ext_test else None
    if name in used: cat = "C"
    elif not ext_prod and not ext_test: cat = "A"
    else: cat = "B"
    res[cat].append((name, ln, ext_prod, ext_test))
for c in "AB":
    print("==", c)
    for name, ln, ep, et in res[c]:
        print(f"{ln:4} {name:35} prod={sorted(set(ep))} test={len(set(et))}")
print("== C (used internally, also external):")
for name, ln, ep, et in res["C"]:
    if ep or et: print(f"{ln:4} {name:35} prod={sorted(set(ep))} test={len(set(et))}")
EOF
python "$TEMP/tk020_an.py"

